--
-- Table structure for table `exam_registrationpanchayat`
--

DROP TABLE IF EXISTS `exam_registrationpanchayat`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `exam_registrationpanchayat` (
  `panchayat_id` int NOT NULL AUTO_INCREMENT,
  `state_id` int NOT NULL,
  `district_id` int NOT NULL,
  `name` varchar(100) NOT NULL,
  `local_body` varchar(30) DEFAULT 'Panchayath',
  PRIMARY KEY (`panchayat_id`),
  UNIQUE KEY `unique_state_district_panchayat` (`state_id`,`district_id`,`name`),
  KEY `fk_registrationdistrict_id` (`district_id`),
  CONSTRAINT `fk_registrationdistrict_id` FOREIGN KEY (`district_id`) REFERENCES `exam_registrationdistrict` (`district_id`),
  CONSTRAINT `fk_registrationstate_id` FOREIGN KEY (`state_id`) REFERENCES `exam_registrationstate` (`state_id`)
) ENGINE=InnoDB AUTO_INCREMENT=35330 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

